{"task": "Find all ERROR level logs that mention .log files", "sql": "SELECT * FROM logs WHERE level = 'ERROR' AND regexp_like(message, '\\.log\\b')"}
{"task": "Identify WARN messages containing temporary file extensions", "sql": "SELECT * FROM logs WHERE level = 'WARN' AND regexp_like(message, '\\.(tmp|temp|bak)\\b')"}
{"task": "List all service logs that reference configuration files", "sql": "SELECT * FROM logs WHERE regexp_like(message, '\\.(conf|config|cfg)\\b')"}
{"task": "Find database-related log messages with SQL file extensions", "sql": "SELECT * FROM logs WHERE regexp_like(message, '\\.sql\\b') AND service = 'database'"}
{"task": "Show application logs mentioning image files in error contexts", "sql": "SELECT * FROM logs WHERE level = 'ERROR' AND regexp_like(message, '\\.(jpg|png|gif|jpeg)\\b')"}
{"task": "Retrieve all warning messages that include backup file patterns", "sql": "SELECT * FROM logs WHERE level = 'WARN' AND regexp_like(message, '\\.(bak|backup|old)\\b')"}
{"task": "Find service logs with JavaScript or CSS file references", "sql": "SELECT * FROM logs WHERE regexp_like(message, '\\.(js|css)\\b') AND service = 'webserver'"}
{"task": "Identify log entries containing source code file extensions", "sql": "SELECT * FROM logs WHERE regexp_like(message, '\\.(py|java|cpp|c|h)\\b')"}
{"task": "List events where users accessed files with specific extensions", "sql": "SELECT e.* FROM events e JOIN logs l ON l.ts >= e.id::timestamp AND l.ts <= (e.id + 3600)::timestamp WHERE regexp_like(e.path, '\\.(pdf|doc|xls)\\b')"}
{"task": "Find all log messages mentioning compressed files", "sql": "SELECT * FROM logs WHERE regexp_like(message, '\\.(zip|tar|gz|rar|7z)\\b')"}

